--!strict
-- BlasterBuilder: builds each weapon as a stylized sci-fi gun from plain Parts
-- (no meshes or uploaded assets): real gun anatomy - receiver, rail,
-- handguard, magazine, stock, sights, muzzle - in gunmetal with one signature
-- colour panel and a small energy glow. The shapes live in
-- BlasterDesigns.json (generated by tools/blender/gen_blasters.js, rendered for
-- review by tools/blender/preview_blasters.py). Skins swap the whole
-- colour scheme. Guns point along +X with their "show" side facing +Z.
-- Once the sculpted models are imported (MeshLib), each gun is instead a few
-- smooth meshes, one per colour slot, built from the same designs with
-- rounded edges (tools/models/game_meshes.js) - same shape, same skins.

local Designs = require(script.Parent.BlasterDesigns) :: any
local MeshLib = require(script.Parent.Parent.MeshLib)
local GameMeshData = require(script.Parent.Parent.GameMeshData) :: any

local BlasterBuilder = {}

export type Palette = {
	Body: Color3, -- main shell
	Accent: Color3, -- bands, caps, tanks
	Dark: Color3, -- barrels, grip
	Glow: Color3, -- the muzzle glow
	Trim: Color3, -- kept for older callers (same as Accent)
}

local function c(r: number, g: number, b: number): Color3
	return Color3.fromRGB(r, g, b)
end

local function rgb(t: { number }): Color3
	return Color3.fromRGB(t[1], t[2], t[3])
end

BlasterBuilder.WeaponPalettes = {} :: { [string]: Palette }
for id, p in pairs(Designs.palettes) do
	BlasterBuilder.WeaponPalettes[id] = {
		Body = rgb(p.Body), Accent = rgb(p.Accent), Dark = rgb(p.Dark), Glow = rgb(p.Glow), Trim = rgb(p.Accent),
	}
end

BlasterBuilder.SkinPalettes = {
	Ocean = { Body = c(80, 150, 240), Accent = c(200, 236, 255), Dark = c(34, 48, 88), Glow = c(140, 236, 255), Trim = c(200, 236, 255) },
	Inferno = { Body = c(232, 76, 60), Accent = c(255, 196, 120), Dark = c(52, 26, 26), Glow = c(255, 210, 110), Trim = c(255, 196, 120) },
	Golden = { Body = c(255, 202, 76), Accent = c(255, 248, 228), Dark = c(110, 76, 30), Glow = c(255, 242, 175), Trim = c(255, 248, 228) },
	Galaxy = { Body = c(116, 80, 214), Accent = c(246, 160, 226), Dark = c(30, 26, 64), Glow = c(190, 214, 255), Trim = c(246, 160, 226) },
	Neon = { Body = c(44, 48, 72), Accent = c(90, 240, 255), Dark = c(22, 22, 34), Glow = c(255, 110, 226), Trim = c(90, 240, 255) },
	Candy = { Body = c(255, 176, 214), Accent = c(255, 255, 255), Dark = c(170, 90, 140), Glow = c(170, 236, 255), Trim = c(255, 255, 255) },
	Void = { Body = c(58, 40, 96), Accent = c(146, 100, 226), Dark = c(20, 16, 30), Glow = c(200, 130, 255), Trim = c(146, 100, 226) },
	Aurora = { Body = c(56, 86, 124), Accent = c(120, 236, 206), Dark = c(24, 34, 54), Glow = c(180, 140, 255), Trim = c(120, 236, 206) },
	Molten = { Body = c(46, 40, 44), Accent = c(255, 130, 60), Dark = c(24, 20, 22), Glow = c(255, 190, 80), Trim = c(255, 130, 60) },
	Sakura = { Body = c(255, 218, 230), Accent = c(255, 140, 180), Dark = c(120, 76, 96), Glow = c(255, 180, 210), Trim = c(255, 140, 180) },
	Glitch = { Body = c(30, 32, 44), Accent = c(80, 255, 206), Dark = c(14, 14, 22), Glow = c(255, 80, 220), Trim = c(80, 255, 206) },
	Starlight = { Body = c(40, 46, 100), Accent = c(170, 186, 255), Dark = c(18, 20, 44), Glow = c(255, 240, 160), Trim = c(170, 186, 255) },
	VIPGold = { Body = c(255, 206, 60), Accent = c(40, 34, 46), Dark = c(28, 24, 32), Glow = c(255, 240, 160), Trim = c(40, 34, 46) },
}

function BlasterBuilder.PaletteFor(weaponId: string, skinId: string?): Palette
	local skin = skinId and (BlasterBuilder.SkinPalettes :: any)[skinId]
	return skin or BlasterBuilder.WeaponPalettes[weaponId] or BlasterBuilder.WeaponPalettes.PawBlaster
end

local MATERIALS = { neon = Enum.Material.Neon, glass = Enum.Material.Glass, metal = Enum.Material.Metal, plastic = Enum.Material.SmoothPlastic }

-- `base` places the whole gun (the previews use it for a 3/4 angle).
function BlasterBuilder.Build(weaponId: string, skinId: string?, base: CFrame?, scale: number?): Model
	local pal = BlasterBuilder.PaletteFor(weaponId, skinId) :: any
	local origin = base or CFrame.identity
	local s = scale or 1
	local tip = Vector3.new(-math.huge, 0, 0) -- frontmost point, for the muzzle
	local model = Instance.new("Model")
	model.Name = weaponId

	local function part(className: string, size: Vector3, cf: CFrame, piece: any, shape: Enum.PartType?): BasePart
		local p = Instance.new(className) :: BasePart
		p.Anchored = true
		p.CanCollide = false
		p.CanQuery = false
		p.CanTouch = false
		p.CastShadow = false
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		if shape then
			(p :: Part).Shape = shape
		end
		p.Size = size * s
		p.CFrame = origin * CFrame.new(cf.Position * s) * cf.Rotation
		p.Color = pal[piece.c] or pal.Body
		-- Explicit material, else the slot's default (Body metal, Glow neon...).
		local slotMaterial = Designs.materials and Designs.materials[piece.c]
		p.Material = MATERIALS[piece.m or slotMaterial or ""] or Enum.Material.SmoothPlastic
		p.Transparency = piece.t or 0
		p.Parent = model
		return p
	end

	local function add(piece: any)
		local pos = Vector3.new(piece.pos[1], piece.pos[2], piece.pos[3])
		local r = piece.rot or { 0, 0, 0 }
		local cf = CFrame.new(pos) * CFrame.Angles(math.rad(r[1]), math.rad(r[2]), math.rad(r[3]))
		local reach = 0
		if piece.k == "pill" then
			-- Rounded capsule: a cylinder with a ball on each end.
			local mid = math.max(0.01, piece.len - piece.d)
			part("Part", Vector3.new(mid, piece.d, piece.d), cf, piece, Enum.PartType.Cylinder)
			for _, side in ipairs({ -1, 1 }) do
				part("Part", Vector3.one * piece.d, cf * CFrame.new(side * mid / 2, 0, 0), piece, Enum.PartType.Ball)
			end
			reach = piece.len / 2
		elseif piece.k == "cyl" then
			part("Part", Vector3.new(piece.len, piece.d, piece.d), cf, piece, Enum.PartType.Cylinder)
			reach = piece.len / 2
		elseif piece.k == "ball" then
			part("Part", Vector3.one * piece.d, cf, piece, Enum.PartType.Ball)
			reach = piece.d / 2
		elseif piece.k == "wedge" then
			part("WedgePart", Vector3.new(piece.size[1], piece.size[2], piece.size[3]), cf, piece)
		else
			part("Part", Vector3.new(piece.size[1], piece.size[2], piece.size[3]), cf, piece)
			reach = piece.size[1] / 2
		end
		if piece.pos[1] + reach > tip.X then
			tip = Vector3.new(piece.pos[1] + reach, piece.pos[2], 0)
		end
	end

	local id = if Designs.designs[weaponId] then weaponId else "PawBlaster"
	local meshed = GameMeshData.Guns[id]
	if meshed and MeshLib.Has(meshed.Parts[1].Name) then
		for _, piece in ipairs(meshed.Parts) do
			local m = MeshLib.Place(piece.Name, origin, s, pal[piece.Slot] or pal.Body, MATERIALS[piece.Material] or Enum.Material.SmoothPlastic, model)
			if m then
				m.CastShadow = false
				m.Transparency = piece.Transparency
			end
		end
		tip = meshed.Tip
	else
		for _, piece in ipairs(Designs.designs[id]) do
			add(piece)
		end
		for _, piece in ipairs(Designs.grip) do
			add(piece)
		end
	end

	-- Invisible marker at the front of the barrel; shots and flashes start here.
	local m = Instance.new("Part")
	m.Name = "MuzzlePoint"
	m.Size = Vector3.one * 0.1
	m.Transparency = 1
	m.Anchored = true
	m.CanCollide = false
	m.CanQuery = false
	m.CanTouch = false
	m.CFrame = origin * CFrame.new((tip + Vector3.new(0.1, 0, 0)) * s)
	m.Parent = model
	return model
end

return BlasterBuilder
